// Title: Save an Aspose.Cells workbook as HTML without grid lines and verify the output in C#
// Common Searches: C# Aspose.Cells export workbook to HTML without grid lines | How to disable grid lines when saving Excel to HTML with Aspose.Cells | Verify that HTML generated by Aspose.Cells does not contain border styles | Aspose.Cells HtmlSaveOptions ExportGridLines false example | Check HTML output for missing cell borders after Aspose.Cells export
// Tags: Aspose.Cells HtmlSaveOptions ExportGridLines false | HTML export without grid lines using Aspose.Cells | C# verify absence of border CSS in generated HTML | disable cell grid lines in Aspose.Cells HTML output | programmatic check for CSS border in Aspose.Cells HTML

using System;
using System.IO;
using Aspose.Cells;

// The sample creates a Workbook, fills cells with data, configures HtmlSaveOptions with ExportGridLines set to false, saves the file as HTML, reads the generated HTML, searches for any "border:" CSS declarations, and prints a message confirming whether grid lines are absent.
class Program
{
    static void Main()
    {
        // Path for the generated HTML file
        string htmlPath = "WorkbookWithoutGridLines.html";

        // 1. Create a new workbook and populate it with sample data
        Workbook workbook = new Workbook();
        Worksheet sheet = workbook.Worksheets[0];
        Cells cells = sheet.Cells;

        // Fill some cells with values
        cells["A1"].PutValue("Product");
        cells["B1"].PutValue("Price");
        cells["A2"].PutValue("Apple");
        cells["B2"].PutValue(1.20);
        cells["A3"].PutValue("Banana");
        cells["B3"].PutValue(0.80);
        cells["A4"].PutValue("Cherry");
        cells["B4"].PutValue(2.50);

        // 2. Configure HTML save options with ExportGridLines disabled
        HtmlSaveOptions saveOptions = new HtmlSaveOptions(SaveFormat.Html);
        saveOptions.ExportGridLines = false; // Disable grid lines

        // 3. Save the workbook to HTML
        workbook.Save(htmlPath, saveOptions);
        Console.WriteLine($"Workbook saved to HTML at: {Path.GetFullPath(htmlPath)}");

        // 4. Verify that grid lines are absent in the generated HTML
        string htmlContent = File.ReadAllText(htmlPath);

        // Simple verification: look for CSS border definitions that Aspose.Cells adds for grid lines.
        // When ExportGridLines is true, the HTML contains "border:" style definitions.
        bool containsBorderStyle = htmlContent.IndexOf("border:", StringComparison.OrdinalIgnoreCase) >= 0;

        if (!containsBorderStyle)
        {
            Console.WriteLine("Verification succeeded: Grid lines are not present in the HTML output.");
        }
        else
        {
            Console.WriteLine("Verification failed: Grid lines appear to be present in the HTML output.");
        }
    }
}
